def display_name(user):
    name = user.get('name')
    if name is None:
        return 'Unknown'
    name = name.strip()
    if not name:
        return 'Unknown'
    return name

from formatter import display_name
def render_users(users):
    names = [display_name(u) for u in users]
    names.sort(key=str.casefold)
    return '\n'.join(names)
